# DrugBank Pharmaceutical Database
import requests

DRUGBANK_API_KEY = "2fc26d35c67cae0be988000da89a8f4023135680b510bd6a376ff32bee3786861094b57ae63ec523b4f49ae871c60026a56901e55cec849013338b8af42b2e78"
BASE_URL = "https://api.drugbank.com/v1"

def get_drug_info(drug_name):
    """Get detailed drug information"""
    response = requests.get(
        f"{BASE_URL}/drugs",
        headers={"Authorization": f"Bearer {DRUGBANK_API_KEY}"},
        params={"name": drug_name}
    )
    return response.json()

def check_drug_interactions(drugs):
    """Check interactions between drugs"""
    response = requests.post(
        f"{BASE_URL}/interactions",
        headers={"Authorization": f"Bearer {DRUGBANK_API_KEY}"},
        json={"drugs": drugs}
    )
    return response.json()
